/**
 * The one tab vocabulary shared by the connector and connection pages.
 *
 * Before this, the two levels had entirely disjoint bars — `Setup / Feeds /
 * Actions` on a connector, `Activity / Actions / Settings` on a connection — so
 * clicking a connection replaced every tab. The one label present in both
 * (`Actions`) moved position *and* changed meaning, which is worse than no
 * overlap at all.
 *
 * Now both levels render the same five tabs in the same order. Only the scope
 * of each tab's contents changes as you descend: `Feeds` on a connector lists
 * what the connector *offers*, on a connection lists what that connection
 * actually *has*. Nothing appears, disappears, or reorders on navigation.
 */
export const CONNECTOR_TABS = [
	{ value: "overview", label: "Overview" },
	{ value: "connections", label: "Connections" },
	{ value: "feeds", label: "Feeds" },
	{ value: "actions", label: "Actions" },
	{ value: "settings", label: "Settings" },
] as const;

export type ConnectorTabValue = (typeof CONNECTOR_TABS)[number]["value"];

/** Parse a `?tab=` search param, falling back to Overview for anything
 * unrecognised so a stale or hand-edited URL still lands on a real tab. */
export function parseConnectorTab(value: unknown): ConnectorTabValue {
	return CONNECTOR_TABS.some((tab) => tab.value === value)
		? (value as ConnectorTabValue)
		: "overview";
}

